SELECT analytics_order_facts.payment_method, SUM(analytics_order_facts.contribution_margin) AS contribution_margin FROM analytics_order_facts WHERE analytics_order_facts.year = 2026 AND analytics_order_facts.month = 9 AND analytics_order_facts.region = 'East' AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.customer_segment = 'education' GROUP BY analytics_order_facts.payment_method ORDER BY contribution_margin DESC, analytics_order_facts.payment_method ASC LIMIT 12
